444	  public reply(
445	    response: TRawResponse | TReply,
446	    body: any,
447	    statusCode?: number,
448	  ) {
449	    const fastifyReply: TReply = this.isNativeResponse(response)
450	      ? new Reply(
451	          response,
452	          {
453	            [kRouteContext]: {
454	              preSerialization: null,
455	              preValidation: [],
456	              preHandler: [],
457	              onSend: [],
458	              onError: [],
459	            },
460	          },
461	          {},
462	        )
463	      : response;
464	
465	    if (!isNil(statusCode)) {
466	      fastifyReply.status(statusCode);
467	    }
468	    if (body instanceof StreamableFile) {
469	      const streamHeaders = body.getHeaders();
470	      if (
471	        fastifyReply.getHeader('Content-Type') === undefined &&
472	        streamHeaders.type !== undefined
473	      ) {
474	        fastifyReply.header('Content-Type', streamHeaders.type);
475	      }
476	      if (
477	        fastifyReply.getHeader('Content-Disposition') === undefined &&
478	        streamHeaders.disposition !== undefined
479	      ) {
480	        fastifyReply.header('Content-Disposition', streamHeaders.disposition);
481	      }
482	      if (
483	        fastifyReply.getHeader('Content-Length') === undefined &&
484	        streamHeaders.length !== undefined
485	      ) {
486	        fastifyReply.header('Content-Length', streamHeaders.length);
487	      }
488	      body = body.getStream();
489	    }
490	    if (
491	      fastifyReply.getHeader('Content-Type') !== undefined &&
492	      fastifyReply.getHeader('Content-Type') !== 'application/json' &&
493	      body?.statusCode >= HttpStatus.BAD_REQUEST
494	    ) {
495	      Logger.warn(
496	        "Content-Type doesn't match Reply body, you might need a custom ExceptionFilter for non-JSON responses",
497	        FastifyAdapter.name,
498	      );
499	      fastifyReply.header('Content-Type', 'application/json');
500	    }
501	    return fastifyReply.send(body);
502	  }
