214	    const prefix = this.config.getGlobalPrefix();
215	    const basePath = addLeadingSlash(prefix);
216	
217	    const conflictPolicy = this.config.getRouteConflictPolicy();
218	    const resolutionStrategy = this.config.getRouteResolutionStrategy();
219	    const adapterIsOrderSensitive =
220	      this.httpAdapter.isRouteOrderSensitive?.() ?? true;
221	    const shouldSortBySpecificity =
222	      resolutionStrategy === 'specificity' && adapterIsOrderSensitive;
223	    // Adapters that are not order-sensitive (e.g. Fastify) currently
224	    // also reject duplicate (method, URL) registrations synchronously
225	    // from the underlying router. Treat the two properties as one
226	    // signal until a separate capability flag is introduced.
227	    const adapterRejectsDuplicates = !adapterIsOrderSensitive;
228	
229	    if (!conflictPolicy && !shouldSortBySpecificity) {
230	      this.routesResolver.resolve(this.httpAdapter, basePath);
231	      return;
232	    }
