247	    // conflict record reflect actual adapter registration order. Without this,
248	    // the reported winner could be the declaration-first (less-specific) route
249	    // even though the sorted-first (more-specific) route is what really wins.
250	    const orderedRoutes = shouldSortBySpecificity
251	      ? RouteSpecificitySorter.sort(resolvedRoutes)
252	      : resolvedRoutes;
253	
254	    const routesToSkip = new Set<ResolvedRoute>();
255	    if (conflictPolicy) {
256	      const filteredPolicy = adapterIsOrderSensitive
257	        ? conflictPolicy
258	        : { duplicate: conflictPolicy.duplicate };
259	
260	      const conflicts = RouteConflictDetector.detect(
261	        orderedRoutes,
262	        this.config.getVersioning(),
263	      );
264	
265	      // On adapters that reject duplicate registrations the policy
266	      // cannot be honoured by simply logging — the adapter would
267	      // throw on the second `instance.route()` call. Drop the
268	      // shadowed route of every duplicate conflict so the detector
269	      // (not the adapter) decides which one wins. The detector
270	      // always picks the earlier-registered route as the winner.
271	      if (adapterRejectsDuplicates) {
272	        conflicts.forEach(conflict => {
273	          if (conflict.kind === 'duplicate') {
274	            routesToSkip.add(conflict.shadowed);
275	          }
276	        });
277	      }
278	
279	      // When specificity sorting is active, shadow conflicts where the sort
280	      // promoted the winner (declared later but more specific) are resolved
281	      // at runtime: the more-specific route is first-registered and handles
282	      // its requests, the less-specific route handles the rest. Filtering
283	      // these out prevents shadow: 'error' from aborting an app whose routes
284	      // work correctly after specificity ordering. Genuine shadows — where the
285	      // winner was already first in declaration order and the sort did not help
286	      // — are kept and still apply the configured policy.
287	      const effectiveConflicts = shouldSortBySpecificity
288	        ? RouteConflictDetector.filterSortResolvedShadows(
289	            conflicts,
290	            resolvedRoutes,
291	          )
292	        : conflicts;
293	
294	      RouteConflictDetector.handle(
295	        effectiveConflicts,
296	        filteredPolicy,
297	        this.logger,
298	      );
299	    }
300	
301	    orderedRoutes.forEach(route => {
302	      if (routesToSkip.has(route)) return;
303	      this.routesResolver.registerResolvedRoute(this.httpAdapter, route);
304	    });
305	  }
