388	  public async listen(port: number | string, ...args: any[]): Promise<any> {
389	    this.assertNotInPreviewMode('listen');
390	
391	    if (!this.isInitialized) {
392	      await this.init();
393	    }
394	
395	    const httpAdapterHost = this.container.getHttpAdapterHostRef();
396	    return new Promise((resolve, reject) => {
397	      const errorHandler = (e: any) => {
398	        this.logger.error(e?.toString?.());
399	        reject(e);
400	      };
401	      this.httpServer.once('error', errorHandler);
402	
403	      const isCallbackInOriginalArgs = isFunction(args[args.length - 1]);
404	      const listenFnArgs = isCallbackInOriginalArgs
405	        ? args.slice(0, args.length - 1)
406	        : args;
407	
408	      this.httpAdapter.listen(
409	        port,
410	        ...listenFnArgs,
411	        (...originalCallbackArgs: unknown[]) => {
412	          if (this.appOptions?.autoFlushLogs ?? true) {
413	            this.flushLogs();
414	          }
415	          if (originalCallbackArgs[0] instanceof Error) {
416	            return reject(originalCallbackArgs[0]);
417	          }
418	
419	          const address = this.httpServer.address();
420	          if (address) {
421	            this.httpServer.removeListener('error', errorHandler);
422	            this.isListening = true;
423	
424	            httpAdapterHost.listening = true;
425	            resolve(this.httpServer);
426	          }
427	          if (isCallbackInOriginalArgs) {
428	            args[args.length - 1](...originalCallbackArgs);
429	          }
430	        },
431	      );
432	    });
433	  }
