447	  private formatAddress(address: any): string {
448	    if (isString(address)) {
449	      if (platform() === 'win32') {
450	        return address;
451	      }
452	      const basePath = encodeURIComponent(address);
453	      return `${this.getProtocol()}+unix://${basePath}`;
454	    }
455	
456	    let host = this.host();
457	    if (address && address.family === 'IPv6') {
458	      if (host === '::') {
459	        host = '[::1]';
460	      } else {
461	        host = `[${host}]`;
462	      }
463	    } else if (host === '0.0.0.0') {
464	      host = '127.0.0.1';
465	    }
466	
467	    return `${this.getProtocol()}://${host}:${address.port}`;
468	  }
