600	  private applyInstanceDecoratorIfRegistered<T>(...instances: T[]): T[] {
601	    if (this.appOptions.instrument?.instanceDecorator) {
602	      const decorate = makeSafeInstanceDecorator(
603	        this.appOptions.instrument.instanceDecorator,
604	      );
605	      return instances.map(instance => decorate(instance) as T);
606	    }
607	    return instances;
