610	  private applyFunctionDecoratorIfRegistered(args: [any, any?]): [any, any?] {
611	    if (!this.appOptions.instrument?.instanceDecorator) {
612	      return args;
613	    }
614	    const decorate = makeSafeInstanceDecorator(
615	      this.appOptions.instrument.instanceDecorator,
616	    );
617	
618	    // Decorators may return a non-function value for plain middleware
619	    // functions; fall back to the original argument so the HTTP adapter
620	    // always receives a valid handler.
621	    const decorateFunction = (arg: any) => {
622	      if (!isFunction(arg)) {
623	        return arg;
624	      }
625	      const decorated = decorate(arg);
626	      return isFunction(decorated) ? decorated : arg;
627	    };
628	
629	    // Map over the original arguments to preserve arity: appending a trailing
630	    // `undefined` to a single-argument `use(fn)` call would make Express 5's
631	    // router throw "argument handler must be a function".
632	    return args.map(decorateFunction) as [any, any?];
633	  }
