private installClosingRequestGate() {
  const server = this.httpServer as unknown as http.Server;
  const routing = this.instance.routing;
  server.removeListener('request', routing);
  server.on('request', (req, res) => {
    if (!this.isShuttingDown) {
      routing(req as ..., res as ...);
      return;
    }
    if (req.httpVersionMajor !== 2) {
      res.setHeader('Connection', 'close');
    }
    res.writeHead(HttpStatus.SERVICE_UNAVAILABLE, {
      'Content-Type': 'text/plain',
    });
    res.end('Service Unavailable');
  });

  // Requests that were accepted by the gate above while the application
  // was still running, but that have not reached a route handler yet
  // (e.g. their body is still streaming in), must not enter the Nest
  // pipeline (guards, pipes, interceptors, handlers) once the shutdown
  // has started. Fastify runs "preHandler" hooks after the request body
  // has been fully received and right before the route handler, which is
  // exactly the boundary of "business processing".
  this.instance.addHook('preHandler', (request, reply, done) => {
    if (!this.isShuttingDown) {
      done();
      return;
    }
    if (request.raw.httpVersionMajor !== 2) {
      reply.header('Connection', 'close');
    }
    reply
      .code(HttpStatus.SERVICE_UNAVAILABLE)
      .header('Content-Type', 'text/plain')
      .send('Service Unavailable');
  });
}
```

